using MediatR; using PamirPlastik.Application.Features.Mediator.Queries.FairQueries; using PamirPlastik.Application.Features.Mediator.Results.FairResults; using PamirPlastik.Application.Interfaces; using PamirPlastik.Domain.Entities; namespace PamirPlastik.Application.Features.Mediator.Handlers.FairHandlers { public class GetFairByIdQueryHandler : IRequestHandler<GetFairByIdQuery, GetFairByIdQueryResult> { private readonly IRepository<Fair> _repository; public GetFairByIdQueryHandler(IRepository<Fair> repository) { _repository = repository; } public async Task<GetFairByIdQueryResult> Handle(GetFairByIdQuery request, CancellationToken cancellationToken) { var x = await _repository.GetByIdAsync(request.Id); return new GetFairByIdQueryResult { FairID = x.FairID, Name = x.Name, Location = x.Location, Date = x.Date, Stand = x.Stand, Img1 = x.Img1, Img2 = x.Img2, IsFuture = x.IsFuture }; } } }
